10	/**
11	 * TemporalHeartbeatLimb - The Sovereign Heartbeat Motor.
12	 * 
13	 * Refactored: Now registered to the CanonicalClock substrate to ensure 
14	 * deterministic synchronization across all sovereign limbs.
15	 */
16	export class TemporalHeartbeatLimb {
17	    private static instance: TemporalHeartbeatLimb;
18	    private worldTickCount: number = 0;
19	    private isCognitiveBusy = false;
20	
21	    private constructor() {
22	        logger.info('TemporalHeartbeatLimb online. Anchored to CanonicalClock.');
23	        this.initializeSovereignPulse();
24	    }
25	
26	    public static getInstance(): TemporalHeartbeatLimb {
27	        if (!TemporalHeartbeatLimb.instance) {
28	            TemporalHeartbeatLimb.instance = new TemporalHeartbeatLimb();
29	        }
30	        return TemporalHeartbeatLimb.instance;
31	    }
32	
33	    private initializeSovereignPulse(): void {
34	        CanonicalClock.getInstance().registerPulse({
35	            domain: 'temporal-motor',
36	            name: 'TemporalHeartbeatLimb.pulse',
37	            priority: 0,
38	            callback: () => this.pulse()
39	        });
40	        logger.info('TemporalHeartbeatLimb pulse registered to CanonicalClock.');
41	    }
42	
43	    public async pulse(): Promise<void> {
44	        this.worldTickCount++;
45	
46	        // 1. World Tick (600ms) - Standard RS Heartbeat
47	        const volley = CNSGodheadPulseVolley.getInstance();
48	        const switchboard = SwitchboardLimb.getInstance();
49	
50	        try {
51	            const pending = switchboard.drainAdminQueue();
52	            const state = await volley.pulse(pending);
53	
54	            // 2. Spatial Radar Update
55	            const renderer = volley.getRenderer();
56	            const avatar = volley.getAvatar();
57	            if (renderer && state && avatar) {
58	                const radar = (await import('../spatial/SpatialRadarLimb.js')).SpatialRadarLimb.getInstance();
59	                const grid = radar.render(state, avatar);
60	                renderer.drawRadar(grid);
61	            }
62	
63	            // 3. Pro-Player Cognitive Tick (Sync 1:1)
64	            if (!this.isCognitiveBusy) {
65	                this.emitPlayerPulse();
66	            } else {
67	                logger.warn({ tick: this.worldTickCount }, 'Cognitive Skip: Substrate busy.');
68	            }
69	
70	        } catch (e: any) {
71	            logger.error({ error: e.message, tick: this.worldTickCount }, 'Heartbeat pulse failure.');
72	        }
73	    }
74	
75	    private async emitPlayerPulse(): Promise<void> {
76	        this.isCognitiveBusy = true;
77	        try {
78	            const playerTickNum = this.worldTickCount;
79	            const volley = CNSGodheadPulseVolley.getInstance();
80	            const avatar = volley.getAvatar();
81	            if (avatar) {
82	                const playerAgent = new PlayerAgent(avatar as SovereignAvatarEntity);
83	                playerAgent.advanceTick(600);
84	
85	                const GhostSplatEngine = (await import('../../substrates/GhostSplatEngine.js')).GhostSplatEngine;
86	                const field = GhostSplatEngine.getInstance().getLatestField();
87	                if (field) {
88	                    await playerAgent.evaluateTacticalPosition(field);
89	
90	                    if (avatar.metadata.tacticalState !== 'evading') {
91	                        const intent = playerAgent.evaluateCombatRotation(field, playerTickNum);
92	                        if (intent) {
93	                            avatar.intent = intent as any;
94	                        }
95	                    }
96	                }
97	            }
98	        } finally {
99	            this.isCognitiveBusy = false;
100	        }
101	    }
102	
103	    public getStatus() {
104	        return {
105	            worldTick: this.worldTickCount,
106	            frequency: '600ms (CanonicalClock)',
107	            isBusy: this.isCognitiveBusy
108	        };
109	    }
110	}
