38	        if (this.isObserving) return;
39	
40	        logger.info('[GHOST_VOICE] Awakening the observer mind...');
41	        this.isObserving = true;
42	
43	        // Monitor primary cycle every 5 seconds (low resource overhead)
44	        this.watchInterval = setInterval(() => {
45	            this.pulse();
46	        }, 5000).unref();
47	    }
