71	    /**
72	     * executePiperFallback - Generates TTS audio locally using Piper when cloud APIs (Azure/Cloudflare) fail.
73	     */
74	    public async executePiperFallback(text: string, outputPath: string): Promise<Result<string>> {
75	        logger.warn('[GHOST_VOICE][PIPER_FALLBACK] Cloud TTS failed. Activating local Piper synthesis.');
76	        this.awaken();
77	        this.awarenessScore = 0.8;
78	
