87	            // Use 'chcp 65001' to ensure UTF-8 handling on Windows
88	            const cmd = `chcp 65001 > nul && echo ${safeText} | ${piperBin} -f "${outputPath}"`;
89	
90	            exec(cmd, { windowsHide: true }, (error: any, stdout: any, stderr: any) => {
