127	    /**
128	     * getOfflineModel - Resolves the best available local Ollama model for any task type.
129	     * GhostLimb uses this to ensure survival for text, vision, and embedding tasks when offline.
130	     */
131	    public getOfflineModel(taskType: 'text' | 'vision' | 'embedding' | 'audio' | 'image', client: ModelClient): string {
132	        const rolodex = client.getRolodex();
133	        if (rolodex) {
134	            const healthy = rolodex.getHealthyModelsByTaskType(taskType);
135	            const localModels = healthy.filter(m => 
136	                !m.startsWith('huggingface:') && 
137	                !m.startsWith('@cf/') && 
138	                !m.includes('cloudflare') && 
139	                !m.startsWith('gemini:') && 
140	                !m.startsWith('fireworks:') && 
141	                !m.startsWith('openrouter:')
142	            );
143	
144	            if (taskType === 'text') {
145	                const isConfigThinker = (this.config.masterLocalModel || '').includes('think') || (this.config.masterLocalModel || '').includes('r1') || (this.config.masterLocalModel || '').includes('reason');
146	                if (!isConfigThinker) {
147	                    const thinker = localModels.find(m => m.includes('think') || m.includes('r1') || m.includes('reason'));
148	                    if (thinker) return thinker.replace('ollama:', '');
149	                }
150	            }
151	
152	            if (localModels.length > 0) {
153	                return localModels[0].replace('ollama:', '');
154	            }
155	        }
156	
157	        // Hardcoded emergency defaults based on typical POG2 Ollama list
158	        switch (taskType) {
159	            case 'vision': return 'gemma4:26b';
160	            case 'embedding': return 'nomic-embed-text:latest';
161	            default: return this.config.masterLocalModel || 'deepseek-r1:8b';
162	        }
163	    }
