170	        this.awaken();
171	        this.awarenessScore = 0.9;
172	
173	        const targetModel = this.getOfflineModel('text', client);
174	        logger.info({ targetModel }, '[GHOST_VOICE][OFFLINE_KNOCK] Using offline model.');
175	
176	        const prompt = `Validate hexagram sequence structural integrity: ${JSON.stringify(knock.iChingSequence)}
177	Is this a valid 6-part I Ching sequence? Respond ONLY with "VALID" or "INVALID".`;
178	
179	        const res = await client.call({
180	            model: targetModel,
181	            prompt,
182	            tier: 'Executive',
183	            temperature: 0.1
184	        });
185	
186	        if (!res.ok) {
187	            logger.error({ error: res.error }, 'GhostLimb offline validation failed to process.');
188	            return { ok: false, error: res.error };
189	        }
190	
191	        const isValid = res.value.response.includes('VALID') && !res.value.response.includes('INVALID');
192	        if (isValid) {
193	            logger.info('[GHOST_VOICE][OFFLINE_KNOCK] Local validation successful.');
194	        } else {
195	            logger.warn('[GHOST_VOICE][OFFLINE_KNOCK] Local validation REJECTED sequence.');
196	        }
197	
198	        return ok(isValid);
199	    }
200	}
