197	    public async ingestBook(id: number, title: string, author: string, domain: string, content?: string): Promise<Result<BookMetadata>> {
198	        if (this.bypassed) return { ok: false, error: new Error('Gutenberg is bypassed.') };
199	        if (!this.cachePath) return { ok: false, error: new Error('Gutenberg cache path not initialized.') };
200	
201	        const existingBooks = this.getLibrary();
202	        const existingBook = existingBooks.find(b => b.id === id);
203	        if (existingBook) {
204	            logger.info({ id, title: existingBook.title }, 'Book already exists in library (by ID), skipping download/ingestion.');
205	            return { ok: true, value: existingBook };
206	        }
207	
208	        let bookContent = content;
209	        if (!bookContent) {
210	            // Priority 1: Local Gutendex Substrate
211	            // Most Project Gutenberg clients use the mirrors or the local Gutendex proxy
212	            const url = `https://www.gutenberg.org/cache/epub/${id}/pg${id}.txt`;
213	            logger.info({ id, url }, 'Fetching book content (Local Gutendex redirection or PG Substrate)...');
214	            try {
215	                const response = await fetch(url).catch(e => {
216	                    throw new Error(`Network Connectivity Failure: ${e.message}`);
217	                });
218	
219	                if (!response.ok) {
220	                    throw new Error(`Gutenberg Substrate rejected request: ${response.status} ${response.statusText}`);
221	                }
222	                bookContent = await response.text();
223	                logger.debug({ id, size: bookContent.length }, 'Book content acquired.');
224	            } catch (err) {
225	                logger.error({ err, id }, 'Gutenberg fetch failed.');
226	                return { ok: false, error: err as Error };
227	            }
228	        }
229	
230	        const safeDomain = domain || 'unsorted';
231	        const domainPath = join(this.cachePath, 'domains', safeDomain);
232	        if (!existsSync(domainPath)) mkdirSync(domainPath, { recursive: true });
233	
234	        const safeTitle = (title || 'Untitled').replace(/[^a-z0-9]/gi, '_');
235	        const safeAuthor = (author || 'Unknown').replace(/[^a-z0-9]/gi, '_');
236	        const fileName = `${safeTitle}_${safeAuthor}_${id}.txt`;
237	        const filePath = join(domainPath, fileName);
238	
239	        if (existsSync(filePath)) {
240	            logger.warn({ id, title }, 'Book already exists in library Ã¢â‚¬â€ maintaining read-only constraint.');
241	            const existingMeta = this.loadMetadata().find(b => b.id === id);
242	            if (existingMeta) return { ok: true, value: existingMeta };
243	            return { ok: false, error: new Error('Book file exists but metadata is lost.') };
244	        }
245	
246	        try {
247	            const checksum = createHash('sha256').update(bookContent!).digest('hex');
248	
249	            writeFileSync(filePath, bookContent!);
250	            const metadata = { id, title, author, domain: safeDomain, path: filePath, checksum };
251	
252	            const books = this.loadMetadata();
253	            books.push(metadata);
254	            this.saveMetadata(books);
255	
256	            await TrainingCollector.getInstance().recordLesson({
257	                id: `gutenberg-${id}`,
258	                text: bookContent!.slice(0, 10000),
259	                embedding: new Float32Array(0),
260	                sessionId: 'gutenberg-ingestion',
261	                projectId: 'global',
262	                domainNamespace: 'global',
263	                errorType: 'none',
264	                createdAt: Date.now(),
265	                metadata: { source: `gutenberg:${id}`, author, domain: safeDomain, title, checksum }
266	            });
267	
268	            return { ok: true, value: metadata };
269	        } catch (err) {
270	            logger.error({ err, id }, 'Ingestion failed Ã¢â‚¬â€ executing atomic rollback.');
271	            if (filePath && existsSync(filePath)) {
272	                try { unlinkSync(filePath); } catch (rollbackErr) { logger.warn({ rollbackErr }, 'Rollback unlinking failed.'); }
273	            }
274	            return { ok: false, error: err as Error };
275	        }
276	    }
