307	    public syncLibrary(): Result<string> {
308	        try {
309	            logger.info('Initiating library synchronization with substrate alignment...');
310	            const domainsPath = join(this.cachePath, 'domains');
311	            const sovereignPath = join(getGutenbergPath(), 'domains');
312	
313	            const searchPaths = [domainsPath];
314	            if (existsSync(sovereignPath) && sovereignPath !== domainsPath) searchPaths.push(sovereignPath);
315	
316	            const activeFiles: string[] = [];
317	            for (const root of searchPaths) {
318	                const queue = [root];
319	                while (queue.length > 0) {
320	                    const current = queue.pop()!;
321	                    const items = readdirSync(current);
322	                    for (const item of items) {
323	                        const fullPath = join(current, item);
324	                        if (statSync(fullPath).isDirectory()) {
325	                            queue.push(fullPath);
326	                        } else if (fullPath.endsWith('.txt')) {
327	                            activeFiles.push(fullPath);
328	                        }
329	                    }
330	                }
331	            }
332	
333	            const currentMetadata = this.loadMetadata();
334	            const validMetadata: BookMetadata[] = [];
335	            let updatedCount = 0;
336	            let removedCount = 0;
337	            let addedCount = 0;
338	            const seenIds = new Set<number>();
339	            const seenPaths = new Set<string>();
340	
341	            // 1. Validate existing metadata
342	            for (const book of currentMetadata) {
343	                if (seenIds.has(book.id)) {
344	                    removedCount++;
345	                    continue;
346	                }
347	
348	                // Align path if it shifted between substrates
349	                if (!existsSync(book.path)) {
350	                    // Try to align using the current active gutenberg path
351	                    const currentGutenberg = getGutenbergPath();
352	                    const fileName = book.path.split(/[\\/]/).pop();
353	                    if (fileName) {
354	                        const potentialPath = join(currentGutenberg, 'domains', book.domain, fileName);
355	                        if (existsSync(potentialPath)) {
356	                            book.path = potentialPath;
357	                            updatedCount++;
358	                        } else {
359	                            removedCount++;
360	                            continue;
361	                        }
362	                    }
363	                }
364	
365	                // Try to infer gutendex_id from filename (if it's pgXXXX.txt)
366	                const pgMatch = book.path.match(/pg(\d+)\.txt$/i);
367	                if (pgMatch) book.gutendex_id = parseInt(pgMatch[1]);
368	
369	                validMetadata.push(book);
370	                seenIds.add(book.id);
371	                seenPaths.add(book.path);
372	            }
373	
374	            // 2. Discover untracked books on disk
375	            for (const filePath of activeFiles) {
376	                if (seenPaths.has(filePath)) continue;
377	
378	                // Extract metadata from filename (format: Title_Author_ID.txt or pgID.txt)
379	                const fileName = filePath.split(/[\\/]/).pop() || '';
380	                let id = Math.floor(Math.random() * 1000000); // Fallback
381	                let title = 'Untitled';
382	                let author = 'Unknown';
383	                let domain = 'unsorted';
384	
385	                // Path contains domains subfolder
386	                const pathParts = filePath.split(/[\\/]/);
387	                const domainIndex = pathParts.indexOf('domains');
388	                if (domainIndex !== -1 && domainIndex < pathParts.length - 2) {
389	                    domain = pathParts[domainIndex + 1];
390	                }
391	
392	                const pgMatch = fileName.match(/pg(\d+)\.txt$/i);
393	                const tripleMatch = fileName.match(/(.*)_(.*)_(\d+)\.txt$/i);
394	
395	                if (pgMatch) {
396	                    id = parseInt(pgMatch[1]);
397	                    title = `Gutenberg Book ${id}`;
398	                } else if (tripleMatch) {
399	                    title = tripleMatch[1].replace(/_/g, ' ');
400	                    author = tripleMatch[2].replace(/_/g, ' ');
401	                    id = parseInt(tripleMatch[3]);
402	                }
403	
404	                if (seenIds.has(id)) {
405	                    id = id + 1000000; // Collision avoidance for manual imports
406	                }
407	
408	                const content = readFileSync(filePath, 'utf8');
409	                const checksum = createHash('sha256').update(content).digest('hex');
410	
411	                validMetadata.push({
412	                    id,
413	                    gutendex_id: pgMatch ? id : undefined,
414	                    title,
415	                    author,
416	                    domain,
417	                    path: filePath,
418	                    checksum
419	                });
420	                seenIds.add(id);
421	                addedCount++;
422	            }
423	
424	            this.saveMetadata(validMetadata);
425	            const msg = `Library Synced. ${validMetadata.length} books healthy (Added: ${addedCount}, Aligned: ${updatedCount}, Removed: ${removedCount}).`;
426	            logger.info(msg);
427	            return { ok: true, value: msg };
428	        } catch (err) {
429	            logger.error({ err }, 'Sync failed due to substrate error.');
430	            return { ok: false, error: err as Error };
431	        }
432	    }
