58	            case EmotionalState.Agitated: speed = 1.25; pitch = 1.15; jitterMult = 1.5; break;
59	            case EmotionalState.Surprised: speed = 1.2; pitch = 1.3; jitterMult = 1.8; break;
60	            case EmotionalState.Inspired: speed = 1.1; pitch = 1.1; break;
61	            case EmotionalState.Decisive: speed = 1.05; pitch = 1.1; break;
62	        }
63	
64	        // 2. Character Trait Alignment
65	        if (characterTraits) {
66	            const traits = characterTraits.toLowerCase();
67	            if (traits.includes('fast') || traits.includes('quick') || traits.includes('erratic')) speed += 0.15;
68	            if (traits.includes('slow') || traits.includes('ponderous') || traits.includes('ancient')) speed -= 0.2;
69	            if (traits.includes('high') || traits.includes('squeaky') || traits.includes('child')) pitch += 0.2;
70	            if (traits.includes('low') || traits.includes('deep') || traits.includes('booming')) pitch -= 0.25;
71	            if (traits.includes('anxious') || traits.includes('shaky')) jitterMult *= 2.0;
