74	        // 3. Fine-grained adjustment from per-scene ProsodyVector (The "Soul")
75	        if (sceneProsody) {
76	            speed -= (sceneProsody.darkTone * 0.25);
77	            pitch -= (sceneProsody.darkTone * 0.30);
78	            speed += (sceneProsody.chaos * 0.30);
