80	            pitch += (sceneProsody.whimsy * 0.25);
81	            speed += (sceneProsody.whimsy * 0.15);
82	        }
83	
84	        // Clamp values
85	        speed = Math.max(0.5, Math.min(1.8, speed));
86	        // 4. Metabolic Aesthetics Override (Phase 13)
87	        if (aes) {
88	            // Scale influences pacing
89	            if (aes.scale === 'Grand') speed *= 0.9; // Slightly more epic/slow
90	            if (aes.scale === 'Abstract') jitterMult *= 1.3; // More erratic
91	
92	            // Thermal variance influences jitter/chaos directly
93	            jitterMult += aes.thermalVariance * 0.5;
94	        }
