99	    /**
100	     * splitTextIntoSegments - Splits text into punctuation-aware chunks for pacing.
101	     */
102	    private splitTextIntoSegments(text: string): Array<{ text: string; pauseAfterMs: number }> {
103	        // Match segments ending with punctuation or end of string, including dash cases
104	        const regex = /[^.!?\n,;â€”]+[.!?\n,;â€”]*/g;
105	        const matches = text.match(regex) || [text];
106	
107	        return matches.map(segment => {
108	            const trimmed = segment.trim();
109	            if (!trimmed || trimmed.length < 2) return null; // Skip tiny fragments
110	
111	            let pause = 0;
112	            if (/[.!?\n]/.test(segment)) {
113	                pause = 600; // Increased full stop pause for cinematic weight
114	            } else if (/[,;â€”]/.test(segment)) {
115	                pause = 300; // Increased minor pause
116	            }
117	
118	            return { text: trimmed, pauseAfterMs: pause };
119	        }).filter((s): s is { text: string; pauseAfterMs: number } => s !== null);
120	    }
