122	    /**
123	     * narrate - Generate a narration artifact for a given text.
124	     * 
125	     * Refinement: Splits text by punctuation, adds prosody jitter, and merges via FFmpeg.
126	     */
127	    public async narrate(text: string, options: NarrationOptions = {}): Promise<Result<NarrationResult>> {
128	        const persona = options.personality || 'Sovereign Narrator';
129	        const segments = this.splitTextIntoSegments(text);
130	        const baseProsody = this.getEmotionalProsody(options);
131	
132	        logger.info({
133	            personality: persona,
134	            traits: options.characterTraits,
135	            segments: segments.length,
136	            baseSpeed: baseProsody.speed.toFixed(2),
137	            basePitch: baseProsody.pitch.toFixed(2),
138	            jitterMult: baseProsody.jitterMult.toFixed(2)
139	        }, 'Initiating multi-part character-aware neural speech synthesis...');
140	
141	        const tmpDir = join(process.cwd(), 'tmp', `voice-${Date.now()}`);
142	        const { mkdirSync, existsSync, writeFileSync, rmSync } = await import('fs');
143	        const { execSync } = await import('child_process');
144	
145	        if (!existsSync(tmpDir)) mkdirSync(tmpDir, { recursive: true });
146	
147	        try {
148	            let totalEstimatedDuration = 0;
149	
150	            // 1. Generate segments in parallel
151	            const tasks = segments.map(async (segment, i) => {
152	                // Apply aggressive jitter (Ã‚Â±10%) to vary the monotone
153	                // Chaos and Agitation increase the range of the jitter
154	                const baseJitter = 0.1 * baseProsody.jitterMult;
155	                const jitterRange = baseJitter + ((options.prosody?.chaos ?? 0) * 0.2);
156	
157	                const speedJitter = baseProsody.speed * (1.0 + (Math.random() - 0.5) * jitterRange);
158	                const pitchJitter = baseProsody.pitch * (1.0 + (Math.random() - 0.5) * jitterRange);
159	
160	                logger.debug({ i, text: segment.text.substring(0, 20), speedJitter: speedJitter.toFixed(2), pitchJitter: pitchJitter.toFixed(2) }, 'Synthesizing segment with character jitter');
161	
162	                let res: Result<Buffer>;
163	                if (this.cfServices) {
164	                    res = await this.cfServices.runAi<Buffer>('@cf/myshell-ai/melotts', {
165	                        text: segment.text,
166	                        service: 'tts', // Hint for some routers
167	                        speaker: 'en-us-male-1' // Common MeloTTS speaker
168	                    });
169	                } else {
170	                    res = await this.client.callCloudflareTTS(segment.text, {
171	                        speed: speedJitter,
172	                        pitch: pitchJitter
173	                    });
174	                }
175	
176	                if (!res.ok || !res.value || res.value.length < 100) {
177	                    logger.warn({ index: i, reason: !res.ok ? 'Error' : 'Empty/Small Buffer' }, 'Cloudflare TTS failed or returned invalid data. Dropping to Ghost Piper fallback.');
178	                    const ghost = new GhostLimb(this.config);
179	                    const segPath = join(tmpDir, `seg-${i}.wav`);
180	                    const fallbackRes = await ghost.executePiperFallback(segment.text, segPath);
181	                    if (!fallbackRes.ok) throw fallbackRes.error;
182	                    return { path: segPath, pause: segment.pauseAfterMs, text: segment.text };
183	                }
184	
185	                const segPath = join(tmpDir, `seg-${i}.wav`);
186	                writeFileSync(segPath, res.value);
187	
188	                logger.debug({ i, path: segPath, size: res.value.length }, 'Segment synthesized successfully');
189	
190	                // Track for ffmpeg
191	                return { path: segPath, pause: segment.pauseAfterMs, text: segment.text };
192	            });
193	
194	            const results = await Promise.all(tasks);
195	
196	
197	            // 2. Concatenate with silences via FFmpeg
198	            if (options.outputPath) {
199	                const outDir = dirname(options.outputPath);
200	                if (!existsSync(outDir)) {
201	                    mkdirSync(outDir, { recursive: true });
202	                }
203	
204	                const inputs = results.map(r => `-i "${r.path}"`).join(' ');
205	
206	                let complexFilter = '';
207	                let concatInputs = '';
208	
209	                results.forEach((res, i) => {
210	                    // Mapped input for the voice segment itself
211	                    concatInputs += `[${i}:a]`;
212	
213	                    if (res.pause > 0) {
214	                        const silenceDur = res.pause / 1000;
215	                        const silenceId = `s${i}`;
216	                        // Generate silence as an independent source
217	                        complexFilter += `anullsrc=r=44100:cl=mono:d=${silenceDur}[${silenceId}]; `;
218	                        concatInputs += `[${silenceId}]`;
219	                    }
220	                });
221	
222	                const totalInputs = results.reduce((acc, r) => acc + (r.pause > 0 ? 2 : 1), 0);
223	                complexFilter += `${concatInputs}concat=n=${totalInputs}:v=0:a=1[outa]`;
224	
225	                const cmd = `ffmpeg -y ${inputs} -filter_complex "${complexFilter}" -map "[outa]" "${options.outputPath}"`;
226	
227	                try {
228	                    execSync(cmd, { stdio: 'pipe', windowsHide: true });
229	                } catch (ffmpegErr: any) {
230	                    const stderr = ffmpegErr.stderr?.toString() || ffmpegErr.message;
231	                    logger.error({ stderr }, 'FFmpeg voice concatenation failed');
232	                    throw new Error(`FFmpeg Concat Failed: ${stderr}`);
233	                }
234	
235	                // Duration estimation refinement
236	                results.forEach(res => {
237	                    const words = res.text.split(/\s+/).length;
238	                    totalEstimatedDuration += (words / 130) * 60 + (res.pause / 1000);
239	                });
240	            }
241	
242	            // Cleanup temp dir
243	            rmSync(tmpDir, { recursive: true, force: true });
244	
245	            return {
246	                ok: true,
247	                value: {
248	                    text,
249	                    personality: persona,
250	                    estimatedDurationSec: Math.round(totalEstimatedDuration),
251	                    status: 'generated',
252	                    audioPath: options.outputPath,
253	                    prosody: options.prosody
254	                }
255	            };
256	
257	        } catch (err: any) {
258	            logger.error({ err: err.message }, 'Multi-part neural speech synthesis FAILED. Attempting GhostLimb Piper Fallback...');
259	            try { if (existsSync(tmpDir)) rmSync(tmpDir, { recursive: true, force: true }); } catch { }
260	
261	            if (options.outputPath) {
262	                const ghost = new GhostLimb(this.config);
263	                const fallbackResult = await ghost.executePiperFallback(text, options.outputPath);
264	                if (fallbackResult.ok) {
265	                    return {
266	                        ok: true,
267	                        value: {
268	                            text,
269	                            personality: persona,
270	                            estimatedDurationSec: Math.round(text.length / 15), // Rough estimate
271	                            status: 'generated',
272	                            audioPath: options.outputPath,
273	                            prosody: options.prosody
274	                        }
275	                    };
276	                }
277	            }
278	
279	            return { ok: false, error: err instanceof Error ? err : new Error(String(err)) };
280	        }
281	    }
