151	        // 1. Core Atmosphere (mutually exclusive weighting)
152	        const lightValue = prosody.whimsy * (1 - prosody.darkTone);
153	        const darkValue = prosody.darkTone * (1 - prosody.whimsy);
154	
155	        if (lightValue > 0.5) {
156	            elements.push('uplifting major key', 'sparkling glockenspiel', 'bright woodwinds');
157	        } else if (darkValue > 0.5) {
158	            elements.push('ominous minor key', 'deep cinematic cello', 'low brass drones');
159	        } else {
160	            elements.push('neutral cinematic ambient', 'soft piano');
161	        }
