163	        // 2. Rhythmic Intensity (Chaos)
164	        if (prosody.chaos > 0.7) {
165	            elements.push('fast frantic percussion', 'dissonant staccato synths');
166	        } else if (prosody.chaos > 0.4) {
167	            elements.push('steady rhythmic pulse', 'ticking clockwork elements');
168	        }
169	
170	        // 3. Structural Integrity (Coherence)
171	        if (prosody.coherence < 0.4) {
172	            elements.push('abstract ethereal textures', 'drifting ambient wash');
173	        } else {
174	            elements.push('clear melodic theme', 'orchestral structure');
