184	    private mapProsodyToSynthParams(prosody: ProsodyVector): SynthParams {
185	        const darkWeight = prosody.darkTone * (1 - prosody.whimsy);
186	        const lightWeight = prosody.whimsy * (1 - prosody.darkTone);
187	
188	        // Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ 1. Derive I-Ching States + Real-time Biasing Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
189	        const contract = this.hexagram.getContract();
190	        const ternary = contract.polarity;
191	        const currentYao = this.hexagram.getYaoState();
192	
193	        // Mix local prosody chaos with global Yao density
194	        let yaoIdx = 1;
195	        if (prosody.chaos > 0.8) yaoIdx = 0;
196	        else if (prosody.chaos > 0.5) yaoIdx = 2;
197	
198	        const yaoState = currentYao || yaoIdx; // Use global override if set
199	
200	        // Hexagram String (6-bit logic from prosody metrics)
201	        const hexBits = [
202	            prosody.chaos > 0.5 ? 1 : 0,
203	            prosody.whimsy > 0.5 ? 1 : 0,
204	            prosody.darkTone < 0.5 ? 1 : 0,
205	            prosody.coherence > 0.5 ? 1 : 0,
206	            darkWeight < lightWeight ? 1 : 0,
207	            prosody.chaos > 0.8 || prosody.whimsy > 0.8 ? 1 : 0
208	        ];
209	        const hexagram = hexBits.join('');
210	
211	        // Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬ 2. Derive Audio Parameters Ã¢â€â‚¬Ã¢â€â‚¬Ã¢â€â‚¬
212	        // Base Freq: Yin=Low (minor/dark), Yang=High (major/bright)
213	        const baseFreq = ternary === CognitivePolarity.YIN ? 55 : ternary === CognitivePolarity.YANG ? 110 : 73.42; // A1, A2, D2
214	
215	        // BPM / Sequence Rate based on Yao
216	        const bps = yaoState === 0 ? 8 : yaoState === 2 ? 4 : yaoState === 3 ? 1 : 2; // Beats per second
217	
218	        // FX & Atmosphere parameters
219	        const lpfCutoff = 400 + lightWeight * 4000 + prosody.chaos * 2000;
220	        const delayMs = bps === 8 ? 250 : 500;
221	
222	        return {
223	            ternary, yaoState, hexagram,
224	            baseFreq, bps, lpfCutoff, delayMs,
225	            chaos: prosody.chaos,
226	            whimsy: prosody.whimsy,
227	            coherence: prosody.coherence
228	        };
229	    }
