231	    private buildFilterGraph(params: SynthParams, duration: number): string {
232	        const { baseFreq, bps, hexagram, ternary, chaos, lpfCutoff, delayMs } = params;
233	
234	        // 1. Algorithmic Sequencer (The Hexagram Melody)
235	        // Convert the 6-bit hexagram into a mathematical step sequence.
236	        // E.g., '101100' -> arr[mod(trunc(t*bps), 6)] -> yields base multipliers
237	        const stepMultipliers = hexagram.split('').map((bit: string) =>
238	            bit === '1' ? (ternary === CognitivePolarity.YIN ? 1.5 : 2.0) : (ternary === CognitivePolarity.YIN ? 1.2 : 1.0)
239	        );
240	
241	        // 1. Voice Definitions
242	        // Sub Bass (Continuous Drone) - Low amplitude to avoid clipping
243	        const bassExpr = `0.3*sin(2*PI*(${baseFreq / 2})*t)`;
244	
245	        // Arp / Lead (Sequenced by Hexagram)
246	        // We use trunc(t*BPS) % 6 to index the step. 
247	        // aevalsrc doesn't have arrays, so we use nested if() or multiple eq() gates.
248	        const seqExpr = stepMultipliers.map((m: number, i: number) => `eq(mod(floor(t*${bps}),6),${i})*${m}`).join('+');
249	        const arpExpr = `0.4*sin(2*PI*(${baseFreq})*(${seqExpr})*t)*(1-mod(t*${bps},1))`; // Plucky envelope
250	
251	        // Noise / Texture (Chaos driven)
252	        const noiseExpr = `${(chaos * 0.1).toFixed(3)}*random(0)`;
253	
254	        // Pad (Whimsy/Coherence driven)
255	        const padExpr = `0.1*(sin(2*PI*${baseFreq}*t)+sin(2*PI*${baseFreq * 1.5}*t))`;
256	
257	        // 2. Mix and Envelopes
258	        const rawMix = `${bassExpr}+${arpExpr}+${noiseExpr}+${padExpr}`;
259	        const fadeIn = 1.0;
260	        const fadeOut = 2.0;
261	        const envelopedEnv = `(${rawMix})*min(1,t/${fadeIn.toFixed(1)})*min(1,(${duration}-t)/${fadeOut.toFixed(1)})`;
262	
263	        // 3. DSP Effects Chain
264	        const dry = 0.5;
265	        const wet = 0.9;
266	        const dspChain = `lowpass=f=${Math.round(lpfCutoff)},chorus=${dry}:${wet}:50:0.4:0.25:2,aecho=0.8:0.9:${delayMs}:0.3,acompressor=threshold=-12dB:ratio=4:attack=5:release=50`;
267	
268	        // Return as a single LAVFI source string for the -i argument
269	        return `aevalsrc='${envelopedEnv}':s=44100:d=${duration},${dspChain}`;
270	    }
