272	    public async healthCheck(): Promise<{ online: boolean; details: string }> {
273	        let hasFfmpeg = false;
274	        try {
275	            execSync('ffmpeg -version', { stdio: 'pipe', timeout: 5000, windowsHide: true });
276	            hasFfmpeg = true;
277	        } catch { /* noop */ }
278	
279	        const details = `Soundtrack: ${hasFfmpeg ? 'ONLINE' : 'DEGRADED'} (${hasFfmpeg ? 'ffmpeg procedural synthesis READY' : 'ffmpeg MISSING, procedural synthesis OFFLINE'})`;
280	
281	        return { online: hasFfmpeg, details };
282	    }
283	}
